def document(title,subtitle):
 d=Document();s=d.sections[0];s.page_width=Cm(21);s.page_height=Cm(29.7);s.top_margin=Cm(2.2);s.bottom_margin=Cm(2);s.left_margin=Cm(2.5);s.right_margin=Cm(2.5)
 for name in ['Normal','Title','Heading 1','Heading 2','Heading 3']:
  st=d.styles[name];st.font.name='Calibri';st.font.color.rgb=RGBColor.from_string('182B3A');st.font.size=Pt(11 if name=='Normal' else 20 if name=='Title' else 15 if name=='Heading 1' else 12)
  st.paragraph_format.space_after=Pt(7);st.paragraph_format.line_spacing=1.12
  for node in list(st.element.xpath('.//w:pBdr')):node.getparent().remove(node)
  rf=st.element.get_or_add_rPr().find(qn('w:rFonts'))
  if rf is not None:
   for a in list(rf.attrib):
    if a.endswith('Theme'):del rf.attrib[a]
 d.add_paragraph(title,'Title');d.add_paragraph(subtitle)
 f=s.footer.paragraphs[0];f.alignment=2;r=f.add_run();field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');r._r.addnext(field)
 return d
def para(d,t):d.add_paragraph(t)
def table(d,headers,rows,widths=None):
 t=d.add_table(rows=1,cols=len(headers));t.style='Table Grid';t.autofit=False
 if widths is None:widths=[16/len(headers)]*len(headers)
 for cells,vals in [(t.rows[0].cells,headers)]+[(t.add_row().cells,row) for row in rows]:
  for c,v,w in zip(cells,vals,widths):
   c.width=Cm(w);c.text=str(v)
   for p in c.paragraphs:
    p.paragraph_format.space_after=Pt(4);p.paragraph_format.space_before=Pt(4);p.paragraph_format.line_spacing=1
    for r in p.runs:r.font.size=Pt(10)
 for r in t.rows:r._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
 t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
 for c in t.rows[0].cells:
  for r in c.paragraphs[0].runs:r.bold=True
 return t

